#!/usr/bin/env node

const { program } = require("commander");
const { createZip } = require("../src/zip");


program
  .command("start")
  .description("Create a zip backup of the current directory")
  .option(
    "--<file>",
    "Exclude additional files or folders (e.g., --dist)",
    (val, memo) => memo.concat(val),
    []
  )
  .action((options) => {
    const customExclusions = options.file || [];
    createZip(customExclusions);
  });

program.parse(process.argv);
